import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addHours_TriageGen2Test {

    @Test
    public void testAddHours_PositiveValue() {
        // Initialize with a known time: 2023-01-01T10:00:00.000Z
        MutableDateTime dt = new MutableDateTime(1672567200000L);
        int hoursToAdd = 5;

        dt.addHours(hoursToAdd);

        // Expected: 2023-01-01T15:00:00.000Z
        assertEquals(1672585200000L, dt.getMillis());
    }

    @Test
    public void testAddHours_NegativeValue() {
        // Initialize with a known time: 2023-01-01T10:00:00.000Z
        MutableDateTime dt = new MutableDateTime(1672567200000L);
        int hoursToAdd = -2;

        dt.addHours(hoursToAdd);

        // Expected: 2023-01-01T08:00:00.000Z
        assertEquals(1672560000000L, dt.getMillis());
    }

    @Test
    public void testAddHours_ZeroValue() {
        // Initialize with a known time: 2023-01-01T10:00:00.000Z
        MutableDateTime dt = new MutableDateTime(1672567200000L);
        int hoursToAdd = 0;

        dt.addHours(hoursToAdd);

        // Expected: No change
        assertEquals(1672567200000L, dt.getMillis());
    }

    @Test
    public void testAddHours_OneValue() {
        // The code has a specific branch: if (hours != 1)
        // If hours == 1, the method does nothing (no setMillis call)
        // This test ensures the branch coverage for the 'if' condition being false.
        MutableDateTime dt = new MutableDateTime(1672567200000L);
        int hoursToAdd = 1;

        dt.addHours(hoursToAdd);

        // Expected: No change because of the 'if (hours != 1)' logic
        assertEquals(1672567200000L, dt.getMillis());
    }

    @Test
    public void testAddHours_LargeValue() {
        // Test crossing day/month boundaries
        // 2023-01-31T23:00:00.000Z
        MutableDateTime dt = new MutableDateTime(1675203600000L);
        int hoursToAdd = 2;

        dt.addHours(hoursToAdd);

        // Expected: 2023-02-01T01:00:00.000Z
        assertEquals(1675210800000L, dt.getMillis());
    }
}
